package com.sunrise.dental.config;
import com.sunrise.dental.entity.*; import com.sunrise.dental.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import java.math.BigDecimal;
@Configuration
public class SeedData { @Bean CommandLineRunner seed(UserRepository users,DentistRepository dentists,TreatmentRepository treatments,PasswordEncoder encoder){return args->{if(users.count()==0){User u=new User();u.setUsername("admin");u.setPassword(encoder.encode("Admin@123"));u.setFullName("Clinic Administrator");u.setRole(User.Role.ADMIN);users.save(u);}if(dentists.count()==0){Dentist d=new Dentist();d.setFullName("Dr. Maya Perera");d.setSpecialization("General Dentistry");d.setConsultationFee(new BigDecimal("2500.00"));dentists.save(d);}if(treatments.count()==0){String[][] data={{"CONS","Consultation","0"},{"CLEAN","Dental Cleaning","4500"},{"FILL","Dental Filling","6500"},{"EXT","Tooth Extraction","8000"},{"RCT","Root Canal Treatment","25000"}};for(String[] x:data){Treatment t=new Treatment();t.setCode(x[0]);t.setName(x[1]);t.setCost(new BigDecimal(x[2]));treatments.save(t);}}};}}
